// specs/hal-engine-conversation-list/spec.md#Over the WebSocket protocol: the validator's half of list_sessions.
describe('the list_sessions frame validator', () => {
  it('accepts limit and a before cursor without the client userId, and rejects a malformed limit or before', () => {
    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    const malformed = [
      {limit: 'ten'},
      {limit: -1},
      {limit: 1.5},
      {before: 'not-an-object'},
      {before: null},
      {before: {updatedAt: before.updatedAt, sessionId: ''}},
      {before: {updatedAt: before.updatedAt, sessionId: 'a'.repeat(129)}},
      {before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {before: {updatedAt: true, sessionId: 's1'}},
    ];

    expect({
      bare: validateMessage({type: 'list_sessions'}),
      full: validateMessage({type: 'list_sessions', limit: 10, before, userId: 'u2'}),
      epoch: validateMessage({type: 'list_sessions', limit: 0, before: {updatedAt: 1767225900000, sessionId: 's3'}}),
      malformed: malformed.map(fields => validateMessage({type: 'list_sessions', ...fields}).valid),
    }).toEqual({
      bare: {valid: true, data: {type: 'list_sessions'}},
      full: {valid: true, data: {type: 'list_sessions', limit: 10, before}},
      epoch: {valid: true, data: {type: 'list_sessions', limit: 0, before: {updatedAt: 1767225900000, sessionId: 's3'}}},
      malformed: malformed.map(() => false),
    });
  });
});
EOF
